1: import React, { useState, useEffect } from \'react\';
2: import { useLocation } from \'react-router-dom\';
3: import { ChevronRight, Users, CheckCircle2, XCircle, Save, ArrowLeft, Search, Calendar, Clock, BookOpen, GraduationCap, Trash2 } from \'lucide-react\';
4: import { collection, query, where, getDocs, doc, writeBatch, serverTimestamp } from \'firebase/firestore\';
5: import { db, pucDb } from \'../../config/firebase\';
6: import { useAuth } from \'../../context/AuthContext\';
7: import { useToast } from \'../../context/ToastContext\';
8: import { PROGRAMS } from \'../../config/academics\';
9: import \'./FacultyAttendance.css\';
10: import CustomSelect from \'../../components/Common/CustomSelect\';
11: import { fetchDynamicSubjects } from \'../../utils/academicsUtils\';
12: 
13: const branchIdMap = {
14:     \'CSE\': \'cse\',
15:     \'ECE\': \'ece\',
16:     \'EEE\': \'eee\',
17:     \'Mechanical\': \'me\',
18:     \'Civil\': \'ce\',
19:     \'Chemical\': \'che\',
20:     \'MME\': \'mme\',
21:     \'AIML\': \'aiml\'
22: };
23: 
24: const BRANCHES = [\'CSE\', \'ECE\', \'EEE\', \'Mechanical\', \'Civil\', \'Chemical\', \'MME\'];
25: const SECTIONS = [\'A\', \'B\', \'C\', \'D\', \'E\', \'F\'];
26: const PERIODS = [1, 2, 3, 4, 5, 6, 7];
27: 
28: const FacultyAttendance = () => {
29:     const { user } = useAuth();
30:     const { showToast } = useToast();
31:     const [step, setStep] = useState(1);
32:     
33:     const [selection, setSelection] = useState({
34:         year: \'\', 
35:         branch: \'\',
36:         section: \'\',
37:         subject: \'\',
38:         date: new Date().toISOString().split(\'T\')[0],
39:         period: 1
40:     });
41: 
42:     const [students, setStudents] = useState([]);
43:     const [attendanceData, setAttendanceData] = useState({}); 
44:     const [loading, setLoading] = useState(false);
45:     const [searchTerm, setSearchTerm] = useState(\'\');
46: 
47:     const [dynamicSubjects, setDynamicSubjects] = useState([]);
48:     const [loadingSubjects, setLoadingSubjects] = useState(false);
49: 
50:     // History feature state
51:     const [showHistoryModal, setShowHistoryModal] = useState(false);
52:     const [historyRecords, setHistoryRecords] = useState([]);
53:     const [loadingHistory, setLoadingHistory] = useState(false);
54:     const [isEditingMode, setIsEditingMode] = useState(false);
55:     const [isSubmitting, setIsSubmitting] = useState(false);
56:     
57:     const location = useLocation();
58: 
59:     useEffect(() => {
60:         if (step === 5 && students.length > 0) {
61:             loadSavedAttendance(selection.date, students);
62:         }
63:     }, [selection.date]);
64: 
65:     useEffect(() => {
66:         if (location.state && location.state.step) {
67:             setSelection(prev => ({
68:                 ...prev,
69:                 year: location.state.year || prev.year,
70:                 branch: location.state.branch || prev.branch,
71:                 section: location.state.section || prev.section,
72:                 subject: location.state.subject || prev.subject
73:             }));
74:             setStep(location.state.step);
75:             
76:             // Clear state so a refresh doesn\'t trigger it again
77:             window.history.replaceState({}, document.title);
78:         }
79:     }, [location.state]);
80: 
81:     useEffect(() => {
82:         if (step === 5 && students.length === 0 && !loading && selection.year && selection.section) {
83:             fetchStudents();
84:         }
85:     }, [step, selection.year, selection.section]);
86: 
87:     useEffect(() => {
88:         if (step === 4 && selection.year && selection.branch) {
89:             const loadSubjects = async () => {
90:                 setLoadingSubjects(true);
91:                 try {
92:                     const programId = selection.year.startsWith(\'btech\') ? \'btech\' : \'puc\';
93:                     const branchId = branchIdMap[selection.branch];
94:                     
95:                     const sem1Subs = await fetchDynamicSubjects(programId, selection.year, branchId, \'sem1\');
96:                     const sem2Subs = await fetchDynamicSubjects(programId, selection.year, branchId, \'sem2\');
97:                     
98:                     setDynamicSubjects([
99:                         { id: \'sem1\', label: \'Semester - I\', subjects: sem1Subs },
100:                         { id: \'sem2\', label: \'Semester - II\', subjects: sem2Subs }
101:                     ]);
102:                 } catch (error) {
103:                     console.error("Failed to load subjects", error);
104:                 } finally {
105:                     setLoadingSubjects(false);
106:                 }
107:             };
108:             loadSubjects();
109:         }
110:     }, [step, selection.year, selection.branch]);
111: 
112:     const updateSelection = (field, value) => {
113:         setSelection(prev => ({ ...prev, [field]: value }));
114:     };
115: 
116:     const fetchStudents = async () => {
117:         if (!selection.year || !selection.section) return;
118:         
119:         setLoading(true);
120:         try {
121:             let targetClass = selection.year;
122:             let targetClasses = [];
123:             if (targetClass === \'puc1\') targetClasses = [\'PUC-01\', \'PUC1\', \'PUC-1\', \'PUC 1\', \'P1\'];
124:             if (targetClass === \'puc2\') targetClasses = [\'PUC-02\', \'PUC2\', \'PUC-2\', \'PUC 2\', \'P2\'];
125:             if (targetClass === \'btech1\') targetClasses = [\'BTECH-01\', \'BTECH-1\', \'B.TECH-1\', \'BTECH 1\', \'B.TECH 1\', \'E-01\', \'E1\', \'E-1\', \'ENGINEERING 1\'];
126:             if (targetClass === \'btech2\') targetClasses = [\'BTECH-02\', \'BTECH-2\', \'B.TECH-2\', \'BTECH 2\', \'B.TECH 2\', \'E-02\', \'E2\', \'E-2\', \'ENGINEERING 2\'];
127:             if (targetClass === \'btech3\') targetClasses = [\'BTECH-03\', \'BTECH-3\', \'B.TECH-3\', \'BTECH 3\', \'B.TECH 3\', \'E-03\', \'E3\', \'E-3\', \'ENGINEERING 3\'];
128:             if (targetClass === \'btech4\') targetClasses = [\'BTECH-04\', \'BTECH-4\', \'B.TECH-4\', \'BTECH 4\', \'B.TECH 4\', \'E-04\', \'E4\', \'E-4\', \'ENGINEERING 4\'];
129: 
130:             let usersRef = collection(db, \'users\');
131:             
132:             // Optimize: Query only users with role \'student\' to massively reduce the download size
133:             const q = query(usersRef, where(\'role\', \'==\', \'student\'));
134:             const snapshot = await getDocs(q);
135:             
136:             // Filter locally by class/year, branch, and section
137:             let data = snapshot.docs
138:                 .map(doc => ({ id: doc.id, ...doc.data() }))
139:                 .filter(s => {
140:                     const classSec = (s.classSection || s.currentClass || \'\').toUpperCase().replace(/\\s+/g, \'\');
141:                     
142:                     // 1. Check Year Match
143:                     let isYearMatch = targetClasses.some(tc => {
144:                         const tcClean = tc.toUpperCase().replace(/\\s+/g, \'\');
145:                         return classSec === tcClean || classSec.startsWith(tcClean + \'-\') || classSec.startsWith(tcClean);
146:                     });
147:                     
148:                     // Fallback: If DB is messy and currentClass is just the branch/section name without a year
149:                     const hasYearIndicator = [\'E1\',\'E2\',\'E3\',\'E4\',\'E-\',\'P1\',\'P2\',\'PUC\',\'BTECH\'].some(y => classSec.includes(y));
150:                     if (!isYearMatch && !hasYearIndicator) {
151:                         if (selection.section && classSec.includes(selection.section.toUpperCase().replace(/\\s+/g, \'\'))) {
152:                             isYearMatch = true;
153:                         }
154:                         if (selection.branch && classSec.includes(selection.branch.toUpperCase().replace(/\\s+/g, \'\'))) {
155:                             isYearMatch = true;
156:                         }
157:                     }
158: 
159:                     if (!isYearMatch) return false;
160: 
161:                     // 2. Check Branch Match
162:                     if (selection.branch && selection.branch !== \'PUC\') {
163:                         const branch = (s.branch || s.department || \'\').toUpperCase();
164:                         const selBranch = selection.branch.toUpperCase();
165:                         if (!branch.includes(selBranch) && !selBranch.includes(branch) && !classSec.includes(selBranch)) {
166:                             return false;
167:                         }
168:                     }
169: 
170:                     // 3. Check Section Match
171:                     if (selection.section && selection.section !== \'All\') {
172:                         const sec = (s.section || \'\').toUpperCase();
173:                         const selSec = selection.section.toUpperCase();
174:                         
175:                         const classSecMatchesSection = classSec.endsWith(`-${selSec}`) || classSec.endsWith(selSec) || classSec.includes(selSec) || classSec === selSec;
176:                         
177:                         if (sec !== selSec && !classSecMatchesSection) {
178:                             return false;
179:                         }
180:                     }
181:                     
182:                     return true;
183:                 });
184: 
185:             data.sort((a, b) => (a.id || \'\').localeCompare(b.id || \'\'));
186: 
187:             setStudents(data);
188:             
189:             // Load saved attendance for the current date, if any
190:             await loadSavedAttendance(selection.date, data);
191:             
192:         } catch (error) {
193:             console.error("Error fetching students:", error);
194:             showToast("Failed to load students", "error");
195:         } finally {
196:             setLoading(false);
197:         }
198:     };
199: 
200:     const handleNext = () => {
201:         if (step === 1 && selection.year) {
202:             if (selection.year.startsWith(\'puc\')) {
203:                 setSelection(prev => ({ ...prev, branch: \'PUC\' }));
204:                 setStep(3);
205:             } else {
206:                 setStep(2);
207:             }
208:         } else if (step === 2 && selection.branch) {
209:             setStep(3);
210:         } else if (step === 3 && selection.section) {
211:             setStep(4);
212:         } else if (step === 4 && selection.subject && selection.date && selection.period) {
213:             setStep(5);
214:             fetchStudents();
215:         }
216:     };
217: 
218:     const handleBack = () => {
219:         if (step > 1) {
220:             if (step === 3 && selection.year.startsWith(\'puc\')) {
221:                 setStep(1);
222:             } else {
223:                 setStep(step - 1);
224:             }
225:         }
226:     };
227: 
228:     const markAll = (status) => {
229:         const newData = { ...attendanceData };
230:         students.forEach(s => {
231:             newData[s.id] = status;
232:         });
233:         setAttendanceData(newData);
234:     };
235: 
236:     const toggleAttendance = (studentId) => {
237:         setAttendanceData(prev => ({
238:             ...prev,
239:             [studentId]: prev[studentId] === \'present\' ? \'absent\' : \'present\'
240:         }));
241:     };
242: 
243:     const handleSubmit = async () => {
244:         if (!students.length) return;
245:         
246:         setIsSubmitting(true);
247:         try {
248:             const batch = writeBatch(db);
249:             const attendanceRef = collection(db, \'attendance\');
250: 
251:             students.forEach(student => {
252:                 const recordId = `${student.id}_${selection.date}_${selection.subject.replace(/\\s+/g, \'\')}`;
253:                 const docRef = doc(attendanceRef, recordId);
254:                 
255:                 batch.set(docRef, {
256:                     studentId: student.id,
257:                     rollNo: student.studentId || student.id,
258:                     name: student.fullName || student.name || \'Unknown\',
259:                     year: selection.year,
260:                     branch: selection.branch,
261:                     section: selection.section,
262:                     subjectId: selection.subject,
263:                     date: selection.date,
264:                     status: attendanceData[student.id] || \'absent\',
265:                     facultyId: user.studentId || user.uid,
266:                     timestamp: serverTimestamp()
267:                 });
268:             });
269: 
270:             await batch.commit();
271:             showToast("Attendance submitted successfully!", "success");
272:             
273:         } catch (error) {
274:             console.error("Error submitting attendance:", error);
275:             showToast("Failed to submit attendance", "error");
276:         } finally {
277:             setIsSubmitting(false);
278:         }
279:     };
280: 
281:     // History Functions
282:     const loadSavedAttendance = async (dateToLoad, currentStudents = students) => {
283:         if (!currentStudents.length) return;
284:         setLoading(true);
285:         try {
286:             const attendanceRef = collection(db, \'attendance\');
287:             const q = query(
288:                 attendanceRef,
289:                 where(\'subjectId\', \'==\', selection.subject),
290:                 where(\'year\', \'==\', selection.year),
291:                 where(\'section\', \'==\', selection.section),
292:                 where(\'date\', \'==\', dateToLoad)
293:             );
294:             
295:             const snapshot = await getDocs(q);
296:             
297:             const newAttendanceData = {};
298:             // First default to present
299:             currentStudents.forEach(s => {
300:                 newAttendanceData[s.id] = \'present\';
301:             });
302:             
303:             // Override with saved records
304:             if (!snapshot.empty) {
305:                 setIsEditingMode(true);
306:                 snapshot.forEach(doc => {
307:                     const data = doc.data();
308:                     if (newAttendanceData[data.studentId] !== undefined) {
309:                         newAttendanceData[data.studentId] = data.status;
310:                     }
311:                 });
312:             } else {
313:                 setIsEditingMode(false);
314:             }
315:             
316:             setAttendanceData(newAttendanceData);
317:         } catch (error) {
318:             console.error("Error loading saved attendance:", error);
319:         } finally {
320:             setLoading(false);
321:         }
322:     };
323: 
324:     const fetchHistory = async () => {
325:         setLoadingHistory(true);
326:         setShowHistoryModal(true);
327:         try {
328:             const attendanceRef = collection(db, \'attendance\');
329:             const q = query(
330:                 attendanceRef,
331:                 where(\'subjectId\', \'==\', selection.subject),
332:                 where(\'year\', \'==\', selection.year),
333:                 where(\'section\', \'==\', selection.section)
334:             );
335:             
336:             const snapshot = await getDocs(q);
337:             
338:             // Group by date
339:             const dateMap = {};
340:             snapshot.forEach(doc => {
341:                 const data = doc.data();
342:                 if (!dateMap[data.date]) {
343:                     dateMap[data.date] = { date: data.date, total: 0, present: 0 };
344:                 }
345:                 dateMap[data.date].total += 1;
346:                 if (data.status === \'present\') {
347:                     dateMap[data.date].present += 1;
348:                 }
349:             });
350:             
351:             // Convert to array and sort descending
352:             const historyArray = Object.values(dateMap).sort((a, b) => new Date(b.date) - new Date(a.date));
353:             setHistoryRecords(historyArray);
354:         } catch (error) {
355:             console.error("Error fetching history:", error);
356:             showToast("Failed to load attendance history", "error");
357:         } finally {
358:             setLoadingHistory(false);
359:         }
360:     };
361: 
362:     const handleDeleteHistoryDate = async (dateToDelete) => {
363:         if (!window.confirm(`Are you sure you want to delete all attendance records for ${selection.subject} on ${dateToDelete}?`)) return;
364: 
365:         setLoadingHistory(true);
366:         try {
367:             const attendanceRef = collection(db, \'attendance\');
368:             const q = query(
369:                 attendanceRef,
370:                 where(\'subjectId\', \'==\', selection.subject),
371:                 where(\'year\', \'==\', selection.year),
372:                 where(\'section\', \'==\', selection.section),
373:                 where(\'date\', \'==\', dateToDelete)
374:             );
375:             
376:             const snapshot = await getDocs(q);
377:             const batch = writeBatch(db);
378:             
379:             snapshot.forEach(doc => {
380:                 batch.delete(doc.ref);
381:             });
382:             
383:             await batch.commit();
384:             showToast(`Attendance for ${dateToDelete} deleted`, "success");
385:             
386:             // If deleting currently viewed date, reload its attendance (which will now default to present)
387:             if (dateToDelete === selection.date) {
388:                 await loadSavedAttendance(selection.date);
389:             }
390:             
391:             // Refresh history list
392:             await fetchHistory();
393:             
394:         } catch (error) {
395:             console.error("Error deleting date attendance:", error);
396:             showToast("Failed to delete attendance", "error");
397:             setLoadingHistory(false); // only on error since fetchHistory clears it on success
398:         }
399:     };
400: 
401:     const handleEditHistoryDate = async (dateToEdit) => {
402:         setShowHistoryModal(false);
403:         setSelection(prev => ({ ...prev, date: dateToEdit }));
404:         await loadSavedAttendance(dateToEdit);
405:         showToast(`Loaded attendance for ${dateToEdit}`, "info");
406:     };
407: 
408:     const filteredStudents = students.filter(s => 
409:         (s.fullName || \'\').toLowerCase().includes(searchTerm.toLowerCase()) || 
410:         (s.studentId || s.id).toLowerCase().includes(searchTerm.toLowerCase())
411:     );
412: 
413:     const renderWizard = () => {
414:         return (
415:             <div className="attendance-wizard">
416:                 <div className="wizard-progress">
417:                     <div className="progress-bar" style={{ width: `${((step - 1) / 4) * 100}%` }}></div>
418:                 </div>
419: 
420:                 {step === 1 && (
421:                     <div className="wizard-step animate-fade-in">
422:                         <h3>Select Academic Year</h3>
423:                         <div className="grid-options">
424:                             {PROGRAMS.map(prog => prog.years.map(year => (
425:                                 <button 
426:                                     key={year.id}
427:                                     className={`option-btn ${selection.year === year.id ? \'selected\' : \'\'}`}
428:                                     onClick={() => { updateSelection(\'year\', year.id); }}
429:                                 >
430:                                     <GraduationCap size={24} className="mb-2 mx-auto" />
431:                                     <span>{year.label}</span>
432:                                 </button>
433:                             )))}
434:                         </div>
435:                         <button 
436:                             className="btn-primary mt-6 w-full flex-center gap-2 py-3"
437:                             disabled={!selection.year}
438:                             onClick={handleNext}
439:                         >
440:                             Next <ChevronRight size={18} />
441:                         </button>
442:                     </div>
443:                 )}
444: 
445:                 {step === 2 && (
446:                     <div className="wizard-step animate-fade-in">
447:                         <div className="flex items-center gap-4 mb-4">
448:                             <button onClick={handleBack} className="btn-icon"><ArrowLeft size={20} /></button>
449:                             <h3>Select Branch</h3>
450:                         </div>
451:                         <div className="grid-options">
452:                             {BRANCHES.map(branch => (
453:                                 <button 
454:                                     key={branch}
455:                                     className={`option-btn ${selection.branch === branch ? \'selected\' : \'\'}`}
456:                                     onClick={() => { updateSelection(\'branch\', branch); }}
457:                                 >
458:                                     <span>{branch}</span>
459:                                 </button>
460:                             ))}
461:                         </div>
462:                         <button 
463:                             className="btn-primary mt-6 w-full flex-center gap-2 py-3"
464:                             disabled={!selection.branch}
465:                             onClick={handleNext}
466:                         >
467:                             Next <ChevronRight size={18} />
468:                         </button>
469:                     </div>
470:                 )}
471: 
472:                 {step === 3 && (
473:                     <div className="wizard-step animate-fade-in">
474:                         <div className="flex items-center gap-4 mb-4">
475:                             <button onClick={handleBack} className="btn-icon"><ArrowLeft size={20} /></button>
476:                             <h3>Select Section</h3>
477:                         </div>
478:                         <div className="grid-options">
479:                             {SECTIONS.map(section => (
480:                                 <button 
481:                                     key={section}
482:                                     className={`option-btn ${selection.section === section ? \'selected\' : \'\'}`}
483:                                     onClick={() => { updateSelection(\'section\', section); }}
484:                                 >
485:                                     <span className="text-xl font-bold">Section {section}</span>
486:                                 </button>
487:                             ))}
488:                         </div>
489:                         <button 
490:                             className="btn-primary mt-6 w-full flex-center gap-2 py-3"
491:                             disabled={!selection.section}
492:                             onClick={handleNext}
493:                         >
494:                             Next <ChevronRight size={18} />
495:                         </button>
496:                     </div>
497:                 )}
498: 
499:                 {step === 4 && (
500:                     <div className="wizard-step animate-fade-in">
501:                         <div className="flex items-center gap-4 mb-6">
502:                             <button onClick={handleBack} className="btn-icon"><ArrowLeft size={20} /></button>
503:                             <h3>Class Details</h3>
504:                         </div>
505:                         
506:                         <div className="form-group mb-6">
507:                             <label className="mb-2 block"><BookOpen size={16}/> Select Subject</label>
508:                             {loadingSubjects ? (
509:                                 <div className="text-center py-4 text-gray-500">Loading subjects...</div>
510:                             ) : (
511:                                 <div className="space-y-6">
512:                                     {dynamicSubjects.map(semester => (
513:                                         semester.subjects.length > 0 && (
514:                                             <div key={semester.id}>
515:                                                 <h4 className="font-semibold text-gray-800 mb-3 border-b pb-2">{semester.label}</h4>
516:                                                 <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
517:                                                     {semester.subjects.map(sub => (
518:                                                         <button
519:                                                             key={sub.id}
520:                                                             className={`p-3 text-left border rounded-xl transition-all ${selection.subject === sub.label ? \'border-primary-main bg-primary-50 shadow-sm\' : \'border-gray-200 hover:border-primary-300 hover:bg-gray-50\'}`}
521:                                                             onClick={() => updateSelection(\'subject\', sub.label)}
